            UniffiLib.uniffi_payjoin_ffi_fn_clone_maybeinputsseentransition(handle, status)
        }
    }

    
    @Throws(ReceiverPersistedException::class)override fun `save`(`persister`: JsonReceiverSessionPersister): OutputsUnknown {
            return FfiConverterTypeOutputsUnknown.lift(
    callWithHandle {
    uniffiRustCallWithError(ReceiverPersistedException) { _status ->
    UniffiLib.uniffi_payjoin_ffi_fn_method_maybeinputsseentransition_save(
        it,
        FfiConverterTypeJsonReceiverSessionPersister.lower(`persister`),_status)
}
    }
    )
    }
    

    
