    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_payjoin_ffi_fn_free_outputsunknowntransition(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_payjoin_ffi_fn_clone_outputsunknowntransition(handle, status)
        }
    }

    
    @Throws(ReceiverPersistedException::class)override fun `save`(`persister`: JsonReceiverSessionPersister): WantsOutputs {
            return FfiConverterTypeWantsOutputs.lift(
    callWithHandle {
    uniffiRustCallWithError(ReceiverPersistedException) { _status ->
    UniffiLib.uniffi_payjoin_ffi_fn_method_outputsunknowntransition_save(
        it,
        FfiConverterTypeJsonReceiverSessionPersister.lower(`persister`),_status)
}
    }
    )
    }
    

    
    @Throws(ReceiverPersistedException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `saveAsync`(`persister`: JsonReceiverSessionPersisterAsync) : WantsOutputs {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_payjoin_ffi_fn_method_outputsunknowntransition_save_async(
                uniffiHandle,
                FfiConverterTypeJsonReceiverSessionPersisterAsync.lower(`persister`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_payjoin_ffi_rust_future_poll_u64(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_payjoin_ffi_rust_future_complete_u64(future, continuation) },
        { future -> UniffiLib.ffi_payjoin_ffi_rust_future_free_u64(future) },
        // lift function
        { FfiConverterTypeWantsOutputs.lift(it) },
        // Error FFI converter
        ReceiverPersistedException.ErrorHandler,
    )
    }

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


