    UniffiLib.uniffi_payjoin_ffi_fn_method_uncheckedoriginalpayloadtransition_save(
        it,
        FfiConverterTypeJsonReceiverSessionPersister.lower(`persister`),_status)
}
    }
    )
    }
    

    
