        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_payjoin_ffi_fn_free_withreplykeytransition(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_payjoin_ffi_fn_clone_withreplykeytransition(handle, status)
        }
    }

    
    @Throws(SenderPersistedException::class)override fun `save`(`persister`: JsonSenderSessionPersister): PollingForProposal {
            return FfiConverterTypePollingForProposal.lift(
    callWithHandle {
    uniffiRustCallWithError(SenderPersistedException) { _status ->
    UniffiLib.uniffi_payjoin_ffi_fn_method_withreplykeytransition_save(
        it,
        FfiConverterTypeJsonSenderSessionPersister.lower(`persister`),_status)
}
    }
    )
    }
    

    
    @Throws(SenderPersistedException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `saveAsync`(`persister`: JsonSenderSessionPersisterAsync) : PollingForProposal {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_payjoin_ffi_fn_method_withreplykeytransition_save_async(
                uniffiHandle,
                FfiConverterTypeJsonSenderSessionPersisterAsync.lower(`persister`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_payjoin_ffi_rust_future_poll_u64(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_payjoin_ffi_rust_future_complete_u64(future, continuation) },
        { future -> UniffiLib.ffi_payjoin_ffi_rust_future_free_u64(future) },
        // lift function
        { FfiConverterTypePollingForProposal.lift(it) },
        // Error FFI converter
        SenderPersistedException.ErrorHandler,
    )
    }

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeWithReplyKeyTransition: FfiConverter<WithReplyKeyTransition, Long> {
    override fun lower(value: WithReplyKeyTransition): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): WithReplyKeyTransition {
        return WithReplyKeyTransition(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): WithReplyKeyTransition {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WithReplyKeyTransition) = 8UL

    override fun write(value: WithReplyKeyTransition, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



