/**
 * Error that may occur when building a receiver session.
 */
sealed class BuildReceiverException: kotlin.Exception(), Disposable  {
    
    /**
     * The provided Bitcoin address is invalid.
     */
    class InvalidAddress(
        
        val v1: AddressParseError
        ) : BuildReceiverException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Error that may occur when converting a value into a URL.
     */
    class IntoUrl(
        
        val v1: IntoUrlError
        ) : BuildReceiverException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BuildReceiverException> {
        override fun lift(error_buf: RustBuffer.ByValue): BuildReceiverException = FfiConverterTypeBuildReceiverError.lift(error_buf)
    }

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is BuildReceiverException.InvalidAddress -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is BuildReceiverException.IntoUrl -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    
}

/**
 * @suppress
 */
public object FfiConverterTypeBuildReceiverError : FfiConverterRustBuffer<BuildReceiverException> {
    override fun read(buf: ByteBuffer): BuildReceiverException {
        

        return when(buf.getInt()) {
            1 -> BuildReceiverException.InvalidAddress(
                FfiConverterTypeAddressParseError.read(buf),
                )
            2 -> BuildReceiverException.IntoUrl(
                FfiConverterTypeIntoUrlError.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BuildReceiverException): ULong {
        return when(value) {
            is BuildReceiverException.InvalidAddress -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeAddressParseError.allocationSize(value.v1)
            )
            is BuildReceiverException.IntoUrl -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeIntoUrlError.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: BuildReceiverException, buf: ByteBuffer) {
        when(value) {
            is BuildReceiverException.InvalidAddress -> {
                buf.putInt(1)
                FfiConverterTypeAddressParseError.write(value.v1, buf)
                Unit
            }
            is BuildReceiverException.IntoUrl -> {
                buf.putInt(2)
                FfiConverterTypeIntoUrlError.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * BIP-78 well-known error code, surfaced to bindings so senders can branch
 * on the code instead of parsing the Display string.
 */

enum class ErrorCode {
    
    /**
     * The payjoin endpoint is not available for now.
     */
    UNAVAILABLE,
    /**
     * The receiver added some inputs but could not bump the fee.
     */
    NOT_ENOUGH_MONEY,
    /**
     * This version of payjoin is not supported.
     */
    VERSION_UNSUPPORTED,
    /**
     * The receiver rejected the original PSBT.
     */
    ORIGINAL_PSBT_REJECTED,
    /**
     * A well-known code newer than this binding understands.
     */
    UNRECOGNIZED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeErrorCode: FfiConverterRustBuffer<ErrorCode> {
    override fun read(buf: ByteBuffer) = try {
        ErrorCode.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ErrorCode) = 4UL

    override fun write(value: ErrorCode, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class FfiValidationException: kotlin.Exception() {
    
    class AmountOutOfRange(
        
        val `amountSat`: kotlin.ULong, 
        
        val `maxSat`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "amountSat=${ `amountSat` }, maxSat=${ `maxSat` }"
    }
    
    class ScriptEmpty(
        
        val `field`: kotlin.String
        ) : FfiValidationException() {
        override val message
            get() = "field=${ `field` }"
    }
    
    class ScriptTooLarge(
        
        val `field`: kotlin.String, 
        
        val `len`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "field=${ `field` }, len=${ `len` }, max=${ `max` }"
    }
    
    class WitnessItemsTooMany(
        
        val `count`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "count=${ `count` }, max=${ `max` }"
    }
    
    class WitnessItemTooLarge(
        
        val `index`: kotlin.ULong, 
        
        val `len`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "index=${ `index` }, len=${ `len` }, max=${ `max` }"
    }
    
    class WitnessTooLarge(
        
        val `len`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "len=${ `len` }, max=${ `max` }"
    }
    
    class WeightOutOfRange(
        
        val `weightUnits`: kotlin.ULong, 
        
        val `maxWu`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "weightUnits=${ `weightUnits` }, maxWu=${ `maxWu` }"
    }
    
    class FeeRateOutOfRange(
        
        val `value`: kotlin.ULong, 
        
        val `unit`: kotlin.String
        ) : FfiValidationException() {
        override val message
            get() = "value=${ `value` }, unit=${ `unit` }"
    }
    
    class ExpirationOutOfRange(
        
        val `seconds`: kotlin.ULong, 
        
        val `max`: kotlin.ULong
        ) : FfiValidationException() {
        override val message
            get() = "seconds=${ `seconds` }, max=${ `max` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiValidationException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiValidationException = FfiConverterTypeFfiValidationError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiValidationError : FfiConverterRustBuffer<FfiValidationException> {
    override fun read(buf: ByteBuffer): FfiValidationException {
        

        return when(buf.getInt()) {
            1 -> FfiValidationException.AmountOutOfRange(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            2 -> FfiValidationException.ScriptEmpty(
                FfiConverterString.read(buf),
                )
            3 -> FfiValidationException.ScriptTooLarge(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            4 -> FfiValidationException.WitnessItemsTooMany(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            5 -> FfiValidationException.WitnessItemTooLarge(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            6 -> FfiValidationException.WitnessTooLarge(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            7 -> FfiValidationException.WeightOutOfRange(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            8 -> FfiValidationException.FeeRateOutOfRange(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> FfiValidationException.ExpirationOutOfRange(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiValidationException): ULong {
        return when(value) {
            is FfiValidationException.AmountOutOfRange -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`amountSat`)
                + FfiConverterULong.allocationSize(value.`maxSat`)
            )
            is FfiValidationException.ScriptEmpty -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
            )
            is FfiValidationException.ScriptTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
                + FfiConverterULong.allocationSize(value.`len`)
                + FfiConverterULong.allocationSize(value.`max`)
            )
            is FfiValidationException.WitnessItemsTooMany -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`count`)
                + FfiConverterULong.allocationSize(value.`max`)
            )
            is FfiValidationException.WitnessItemTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`index`)
                + FfiConverterULong.allocationSize(value.`len`)
                + FfiConverterULong.allocationSize(value.`max`)
            )
            is FfiValidationException.WitnessTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`len`)
                + FfiConverterULong.allocationSize(value.`max`)
            )
            is FfiValidationException.WeightOutOfRange -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`weightUnits`)
                + FfiConverterULong.allocationSize(value.`maxWu`)
            )
            is FfiValidationException.FeeRateOutOfRange -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`value`)
                + FfiConverterString.allocationSize(value.`unit`)
            )
            is FfiValidationException.ExpirationOutOfRange -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`seconds`)
