 * inputs and so resolved the session.
 */

enum class ResolvedBy {
    
    /**
     * The Payjoin proposal.
     */
    PAYJOIN,
    /**
     * The fallback transaction.
     */
    FALLBACK,
    /**
     * Neither the Payjoin proposal nor the fallback, e.g. a fee bump or a
     * sender double-spend.
     */
    UNRECOGNIZED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeResolvedBy: FfiConverterRustBuffer<ResolvedBy> {
    override fun read(buf: ByteBuffer) = try {
        ResolvedBy.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ResolvedBy) = 4UL

    override fun write(value: ResolvedBy, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Represent an error returned by Payjoin receiver.
 */
sealed class ResponseException: kotlin.Exception(), Disposable  {
    
    /**
     * `WellKnown` Errors are defined in the [`BIP78::ReceiverWellKnownError`] spec.
     *
     * It is safe to display `WellKnown` errors to end users.
     *
     * [`BIP78::ReceiverWellKnownError`]: https://github.com/bitcoin/bips/blob/master/bip-0078.mediawiki#user-content-Receivers_well_known_errors
     */
    class WellKnown(
        
        val v1: WellKnownError
        ) : ResponseException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Errors caused by malformed responses.
     */
    class Validation(
        
        val v1: ValidationError
        ) : ResponseException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * `Unrecognized` Errors are NOT defined in the [`BIP78::ReceiverWellKnownError`] spec.
     *
     * It is NOT safe to display `Unrecognized` errors to end users as they could be used
     * maliciously to phish a non technical user. Only display them in debug logs.
     *
     * [`BIP78::ReceiverWellKnownError`]: https://github.com/bitcoin/bips/blob/master/bip-0078.mediawiki#user-content-Receivers_well_known_errors
     */
    class Unrecognized(
        
        val `errorCode`: kotlin.String, 
        
        val `msg`: kotlin.String
        ) : ResponseException() {
        override val message
            get() = "errorCode=${ `errorCode` }, msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ResponseException> {
        override fun lift(error_buf: RustBuffer.ByValue): ResponseException = FfiConverterTypeResponseError.lift(error_buf)
    }

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is ResponseException.WellKnown -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is ResponseException.Validation -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is ResponseException.Unrecognized -> {
                
    Disposable.destroy(
        this.`errorCode`,
        this.`msg`
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    
}

