    }

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is SenderPersistedException.Transient -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is SenderPersistedException.Fatal -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is SenderPersistedException.Storage -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    
}

